package ai.pleos.coach.core
import org.junit.Assert.*
import org.junit.Test
class CoachEngineTest {
 private val school=SampleRoute.segments[0];private val gate=SampleRoute.segments[1]
 private fun pref(goal:Goal=Goal.SIGNAL_CHECK,assistance:Assistance=Assistance.TOGETHER)=Preference(school.id,selected=true,goal=goal,assistance=assistance)
 private fun engine(p:Preference=pref())=CoachEngine(listOf(p),Source.REPLAY,"drive-1",1000)
 private fun frame(t:Long=1000,signal:TurnSignal=TurnSignal.OFF)=Snapshot(t,Source.REPLAY,segmentId=school.id,approachId=school.approachId,speedKmh=32.0,brake=false,signal=signal)
 @Test fun firstDriveRecordsBothWithoutPrompts(){val e=CoachEngine(emptyList(),Source.REPLAY,"first",1000);val u=ReplayFactory.frames(ReplayScenario.FIRST,1000).map(e::ingest);val r=e.finish(33000);assertEquals(2,r.size);assertTrue(u.none{it.decision?.shouldSpeak==true});assertTrue(r.all{it.decision.reason==DecisionReason.NOT_SELECTED})}
 @Test fun matchingSignalSuppressesSignalGoalOnly(){assertEquals(DecisionReason.SIGNAL_ALREADY_ON,engine().ingest(frame(signal=TurnSignal.RIGHT)).decision?.reason);assertTrue(engine(pref(Goal.ROUTE_PREVIEW)).ingest(frame(signal=TurnSignal.RIGHT)).decision!!.shouldSpeak)}
 @Test fun wrongSignalDoesNotSuppress(){assertTrue(engine().ingest(frame(signal=TurnSignal.LEFT)).decision!!.shouldSpeak)}
 @Test fun repeatedFramesDoNotDuplicate(){val e=engine();val u=listOf(e.ingest(frame()),e.ingest(frame()),e.ingest(frame(1500)),e.ingest(frame(1200)));assertEquals(1,u.count{it.decision?.shouldSpeak==true});assertEquals(2,e.finish(2000).single().samples.size)}
 @Test fun staleAndFutureSignalsStayUnknown(){val e=CoachEngine(listOf(pref()),Source.REPLAY,"stale",5000);assertEquals(DecisionReason.DATA_UNAVAILABLE,e.ingest(frame(5000).copy(signalTimestampMs=1000)).decision?.reason);assertNull(e.ingest(frame(5500).copy(signalTimestampMs=6000)).decision);assertTrue(e.ingest(frame(6000)).decision!!.shouldSpeak);assertEquals(TurnSignal.UNKNOWN,e.finish(6500).single().samples.first().signal)}
 @Test fun missingSignalIsNotOff(){val e=engine();assertEquals(DecisionReason.DATA_UNAVAILABLE,e.ingest(frame(signal=TurnSignal.UNKNOWN)).decision?.reason);assertFalse(e.finish(2000).single().decision.shouldSpeak)}
 @Test fun staleSpeedAndBrakeRemainMissing(){val e=CoachEngine(emptyList(),Source.REPLAY,"missing",5000);val s=e.ingest(frame(5000).copy(speedTimestampMs=1000,brakeTimestampMs=1000)).sample!!;assertNull(s.speedKmh);assertNull(s.brake);assertEquals(1,e.finish(5500).single().missingSamples)}
 @Test fun nonFiniteAndReverseSpeedRemainMissing(){val e=engine();assertNull(e.ingest(frame().copy(speedKmh=Double.NaN)).sample!!.speedKmh);assertNull(e.ingest(frame(1500).copy(speedKmh=-4.0)).sample!!.speedKmh)}
 @Test fun staleLocationDefers(){val e=CoachEngine(listOf(pref(Goal.ROUTE_PREVIEW)),Source.REPLAY,"loc",5000);assertEquals(DecisionReason.DATA_UNAVAILABLE,e.ingest(frame(5000).copy(locationTimestampMs=1000)).decision?.reason);assertTrue(e.ingest(frame(5500)).decision!!.shouldSpeak)}
 @Test fun reviewAndSpeedGoalsNeverPrompt(){assertEquals(DecisionReason.REVIEW_ONLY,engine(pref(assistance=Assistance.REVIEW_ONLY)).ingest(frame()).decision?.reason);assertEquals(DecisionReason.SPEED_REVIEW_ONLY,engine(pref(Goal.SPEED_REVIEW)).ingest(frame()).decision?.reason)}
 @Test fun wrongApproachAndOrderRejected(){val e=engine();assertEquals(DecisionReason.APPROACH_UNVERIFIED,e.ingest(frame().copy(approachId="opposite")).decision?.reason);assertEquals(DecisionReason.APPROACH_UNVERIFIED,e.ingest(frame(1500).copy(segmentId=gate.id,approachId=gate.approachId)).decision?.reason);assertTrue(e.finish(2000).isEmpty())}
 @Test fun cancellationInvalidatesDeferredReminder(){val e=engine();e.ingest(frame(signal=TurnSignal.UNKNOWN));assertEquals(DecisionReason.ROUTE_CHANGED,e.ingest(frame(1500).copy(routeActive=false)).decision?.reason);assertNull(e.ingest(frame(2000)).decision);assertEquals(DecisionReason.ROUTE_CHANGED,e.finish(2500).single().decision.reason)}
 @Test fun changedRouteIsNotReused(){val e=engine();e.ingest(frame(signal=TurnSignal.UNKNOWN));e.ingest(frame(1500).copy(routeId="other"));assertNull(e.ingest(frame(2000)).decision)}
 @Test fun lateSignalDoesNotPromptAfterExit(){val e=engine();e.ingest(frame(signal=TurnSignal.UNKNOWN));e.ingest(frame(1500).copy(segmentId=null,approachId=null));assertEquals(DecisionReason.APPROACH_UNVERIFIED,e.ingest(frame(2000)).decision?.reason);assertFalse(e.finish(2500).single().decision.shouldSpeak)}
 @Test fun sourcesNeverBlend(){val e=engine();assertNull(e.ingest(frame().copy(source=Source.LIVE)).sample);assertEquals(Source.REPLAY,e.ingest(frame()).sample!!.source)}
 @Test fun finishIdempotent(){val e=engine();e.ingest(frame());val r=e.finish(2000);assertEquals(r,e.finish(4000));assertNull(e.ingest(frame(5000)).sample)}
 @Test fun historySeparatesApproachAndSource(){val base=engine().let{it.ingest(frame());it.finish(1500).single()};val all=listOf(base.copy(id="r1",startedAtMs=1000),base.copy(id="r2",startedAtMs=2000),base.copy(id="r3",startedAtMs=3000),base.copy(id="live",startedAtMs=4000,source=Source.LIVE),base.copy(id="reverse",startedAtMs=5000,approachId="reverse"));assertEquals(listOf("r3","r2"),RecordHistory.latestTwo(all,school.id,school.approachId,Source.REPLAY).map{it.id});assertEquals(4,RecordHistory.retainLatestTwo(all).size)}
 @Test fun uncertainReasonKeepsChosenGoal(){assertEquals(Goal.SPEED_REVIEW,pref(Goal.SPEED_REVIEW).withReason(Reason.TRAFFIC).goal);assertEquals(Goal.ROUTE_PREVIEW,pref().withReason(Reason.LATE_TURN).goal)}
}
